reg [3:0] state;
	reg [3:0] counter;
	reg [3:0] data_out;
	reg valid_out;
	always @(posedge clk) begin
		if (reset) begin
			state <= 0;
			counter <= 0;
			data_out <= 0;
			valid_out <= 0;
		end
		else begin
			case (state)
				0: begin
					counter <= 0;
					data_out <= 0;
					valid_out <= 0;
					state <= 1;
				end
				1: begin
					counter <= counter + 1;
					data_out <= 0;
					valid_out <= 0;
					if (counter == 10) begin
						state <= 2;
					end
				end
				2: begin
					counter <= 0;
					data_out <= in;
					valid_out <= 1;
					state <= 3;
				end
				3: begin
					counter <= 0;
					data_out <= 0;
					valid_out <= 0;
					state <= 0;
				end
			endcase
		end
	end
endmodule

